}
for text, expected in ok_cases.items():
    got = parse_duration(text)
    assert got == expected and isinstance(got, int), (text, got, expected)
    print("ok", repr(text), got)

bad = ["", "   ", "5x", "10", "5m1h", "1h1h", "-1h", "1h-5m", "abc", "1h..30m",
