       "1.5.5h", "\t", "1h30m extra"]
for text in bad:
    try:
        got = parse_duration(text)
    except ValueError as exc:
        print("ok  raises ValueError for", repr(text))
    else:
        raise AssertionError("%r returned %r, expected ValueError" % (text, got))

try:
    parse_duration(None)
except ValueError:
    print("ok  raises ValueError for None")

print("ALL CHECKS PASSED")
EOF
